def solve(clue):
    T = clue.split()
    n = int(T[0])
    adj = [set() for _ in range(n)]
    for e in T[1:]:
        a, b = e.split('-')
        adj[int(a)].add(int(b))
        adj[int(b)].add(int(a))
    path = []
    used = [False] * n

    def bt(v):
        path.append(v)
        used[v] = True
        if len(path) == n:
            return True
        for u in sorted(adj[v], key=lambda u: len(adj[u])):
            if not used[u] and bt(u):
                return True
        used[v] = False
        path.pop()
        return False

    for st in sorted(range(n), key=lambda v: len(adj[v])):
        if bt(st):
            return ' '.join(str(v) for v in path)
    return ''

